// ── The controls on an answer ──────────────────────────────

function rateButton(cls, svg, aria) {
	var b = document.createElement('button');
	b.type = 'button'; b.className = cls; b.innerHTML = svg;
	b.setAttribute('aria-label', aria); b.title = aria;
	return b;
}

/// One group: up, down, details. An answer wears it in a row under its text, on every
/// device (UNBLOCK-10); a changed-files row wears it at its right end.
function rateGroup() {
	var g = document.createElement('span');
	g.className = 'ctile-rate'; g.dataset.chrome = 'rate';
	g.setAttribute('role', 'group'); g.setAttribute('aria-label', t('rating.aria_group'));
	var up = rateButton('ctile-rate-up', RATE_UP_SVG, t('rating.aria_up'));
	up.setAttribute('aria-pressed', 'false');
	var dn = rateButton('ctile-rate-down', RATE_DOWN_SVG, t('rating.aria_down'));
	dn.setAttribute('aria-pressed', 'false');
	var mo = rateButton('ctile-rate-more', RATE_MORE_SVG, t('rating.aria_more'));
	mo.setAttribute('aria-haspopup', 'dialog');
	g.appendChild(up); g.appendChild(dn); g.appendChild(mo);
	return g;
}

function rateSet(el, name, val) { if (el.getAttribute(name) !== val) el.setAttribute(name, val); }

/// Put the rating row and (for a pending down rating) a chip row on one answer tile,
/// and set what is lit. Idempotent; it touches only chrome, never the tile's own markup.
function rateDress(tile, g, head, burst) {
	var body = tile._body;
	var row = tile.querySelector(':scope > .ctile-rate-row');
	if (!row) {
		row = document.createElement('div');
		row.className = 'ctile-rate-row'; row.dataset.chrome = 'rate';
		row.appendChild(rateGroup());
		body.after(row);
	}
	var st = DaimondRatings.stateWith(head, burst, g.prod.h);
	tile.querySelectorAll('.ctile-rate').forEach(function (grp) { rateLight(grp, st); });
	var d = burst && burst.drafts ? burst.drafts.get(g.prod.h) : null;
	rateDressTags(tile.querySelector(':scope > .ctile-rate-tags'), row, g.form, d && !d.clear && d.s < 0 ? d : null, 'answer');
}

/// Set what a group shows: the lit arrow, and whether details hold more than a bare arrow.
function rateLight(grp, st) {
	rateSet(grp.querySelector('.ctile-rate-up'), 'aria-pressed', st.lit === 'up' ? 'true' : 'false');
	rateSet(grp.querySelector('.ctile-rate-down'), 'aria-pressed', st.lit === 'down' ? 'true' : 'false');
	grp.querySelector('.ctile-rate-more').classList.toggle('on', !!st.detail);
}

/// The chip row of a pending down rating, set after `anchor`; `tags` is the one already
/// there or null, and it is removed when there is no draft. Answers the row now standing.
function rateDressTags(tags, anchor, form, draft, kind) {
	if (!draft) { if (tags) tags.remove(); return null; }
	var ids = form.quickFor(kind, 'down');		// the quick row; Details lists every reason
	if (tags && tags.dataset.ids !== ids.join(',')) { tags.remove(); tags = null; }
	if (!tags) {
		tags = document.createElement('div');
		tags.className = 'tile-dlg-seg ctile-rate-tags'; tags.dataset.chrome = 'rate';
		tags.dataset.ids = ids.join(',');
		tags.setAttribute('role', 'group'); tags.setAttribute('aria-label', t('rating.tags_down'));
		ids.forEach(function (id) {
			var b = document.createElement('button');
			b.type = 'button'; b.className = 'tile-dlg-level'; b.dataset.tag = id;
			b.textContent = rateTagWord(form, id);
			b.setAttribute('aria-pressed', 'false');
			tags.appendChild(b);
		});
		anchor.after(tags);
	}
	tags.querySelectorAll('.tile-dlg-level').forEach(function (b) {
		rateSet(b, 'aria-pressed', draft.tags.indexOf(b.dataset.tag) >= 0 ? 'true' : 'false');
	});
	return tags;
}

/// Bring every answer on screen into step with the transcript and the burst: mount the
/// group where an answer qualifies, refresh what is lit, and sweep it off any tile that
/// no longer does. Runs from `renderHistoryFurniture` and wherever a turn ends.
export function mountRateControls() {
	if (!chatOutput || !pg.current || !window.DaimondRatings || !window.DaimondProvenance) return;
	var form = rateForm(), msgs = pg.current.messages || [], keep = new Set();
	if (form) {
		var byMid = new Map();
		for (var i = 0; i < msgs.length; i++) {
			var m = msgs[i];
			if (m && m.role === 'assistant' && m.mid) byMid.set(String(m.mid), m);
		}
		var idx = DaimondRatings.index(msgs), burst = _rateBurst.get(pg.current.id) || null;
		chatOutput.querySelectorAll('.ctile.chat-msg-assistant[data-mid]').forEach(function (tile) {
			var msg = byMid.get(tile.dataset.mid);
			if (!rateQualifies(msg) || !tile._lbl) return;
			var g = { m: msg, prod: rateProdOf(msg), form: form };
			keep.add(tile);
			rateDress(tile, g, idx.get(g.prod.h) || null, burst);
		});
	}
	chatOutput.querySelectorAll('.ctile-rate, .ctile-rate-row, .ctile-rate-tags').forEach(function (n) {
		if (n.closest('.turn-files')) return;		// a changed-files row's own, kept by `mountFileRates`
		var tile = n.closest('.ctile');
		if (!tile || !keep.has(tile)) n.remove();
	});
	mountFileRates(chatOutput);
}

/// Put a group on each changed-files row that has a record, light it from the transcript and
/// the burst, and (for a pending down rating) set the chip row after the row. A row with no
/// record gets none, and one that lost its record loses it. Idempotent, and chrome only: the
/// row's own markup, `data-h` included, is built with the row.
export function mountFileRates(root) {
	if (!root || !pg.current || !window.DaimondRatings || !window.DaimondProvenance) return;
	var form = rateForm(), msgs = pg.current.messages || [];
	var recs = form ? rateFileRecs() : new Map();
	var idx = form ? DaimondRatings.index(msgs) : null, burst = _rateBurst.get(pg.current.id) || null;
	root.querySelectorAll('.turn-file-row').forEach(function (row) {
		var h = row.dataset.h || '', prod = h ? recs.get(h) : null;
		var grp = row.querySelector(':scope > .turn-file-rate'), nx = row.nextElementSibling;
		var tags = nx && nx.classList.contains('ctile-rate-tags') ? nx : null;
		if (!prod) {
			if (grp) grp.remove();
			if (tags) tags.remove();
			return;
		}
		if (!grp) {
			grp = rateGroup();
			grp.classList.add('turn-file-rate');
			grp.setAttribute('aria-label', t('rating.aria_group_file'));
			var de = row.querySelector(':scope > .turn-file-delta');
			if (de) de.after(grp); else row.appendChild(grp);
		}
		rateLight(grp, DaimondRatings.stateWith(idx.get(h) || null, burst, h));
		var d = burst && burst.drafts ? burst.drafts.get(h) : null;
		rateDressTags(tags, row, form, d && !d.clear && d.s < 0 ? d : null, 'file');
	});
}

/// What a control rates: its changed-files row (a group inside it, or the chip row standing
/// right after it), else its answer's tile.
function rateHostOf(b) {
	var row = b.closest('.turn-file-row');
	if (row) return row;
	var tags = b.closest('.ctile-rate-tags');
	if (tags && tags.closest('.turn-files')) {
		var prev = tags.previousElementSibling;
		return prev && prev.classList.contains('turn-file-row') ? prev : null;
	}
	return b.closest('.ctile');
}
